export const NAVIGATION_MANIFEST = Object.freeze({
  schemaVersion: PUBLIC_MANIFEST.schemaVersion,
  workspaces: Object.freeze(PUBLIC_MANIFEST.workspaces),
  destinations: Object.freeze(PUBLIC_MANIFEST.destinations),
})

export function navigationDestinationsFor() {
  return NAVIGATION_MANIFEST.destinations.slice()
}

export function getNavigationDestination(id) {
  const key = String(id || '').trim()
  return NAVIGATION_MANIFEST.destinations.find(item => item.id === key) || null
}

export function navigationWorkspacesFor() {
  return NAVIGATION_MANIFEST.workspaces.map(workspace => ({
    ...workspace,
    groups: workspace.groups.map(group => ({ ...group, ids: [...group.ids] })),
    ids: [...workspace.ids],
  }))
}

export function navigationManifestFor() {
  return {
    schemaVersion: NAVIGATION_MANIFEST.schemaVersion,
    edition: 'openocti',
    workspaces: navigationWorkspacesFor(),
    destinations: navigationDestinationsFor(),
  }
}

export function isNavigationDestinationActive(destinationId, activeId) {
  const destination = getNavigationDestination(destinationId)
  return !!destination && destination.activeIds.includes(String(activeId || '').trim())
}

export function roleTabsFromNavigationManifest(role) {
  if (role === 'owner' || role === 'admin') return ['*']
  return NAVIGATION_MANIFEST.destinations
    .filter(item => item.roles.includes(role) && item.memberOrder !== null)
    .sort((a, b) => a.memberOrder - b.memberOrder)
    .map(item => item.id)
}

export function routeAliasesFor() {
  const aliases = {}
  for (const destination of NAVIGATION_MANIFEST.destinations) {
    for (const legacyId of destination.legacyIds) aliases[legacyId] = destination.id
  }
  return aliases
}
